"use strict";

const { randomUUID } = require("node:crypto");
const Spot = require("../models/Spot");
const Vehicle = require("../models/Vehicle");
const Transaction = require("../models/Transaction");

const GATE_IDS = new Set(["Entry-1", "Entry-2"]);

/**
 * Claim the first available spot in the matching vehicle zone and create an
 * entry transaction. The spot update is atomic, so concurrent requests cannot
 * reserve the same free spot.
 *
 * entryTimestamp is generated by this service, never accepted from the client,
 * so FCFS ordering uses server-received time.
 */
async function allocateSpot({
  plateNumber,
  vehicleType,
  gateId,
  operatorId,
}) {
  if (typeof plateNumber !== "string" || !plateNumber.trim()) {
    const error = new TypeError("plateNumber is required");
    error.statusCode = 400;
    error.code = "INVALID_INPUT";
    throw error;
  }

  if (!["2W", "4W"].includes(vehicleType)) {
    const error = new TypeError("vehicleType must be either '2W' or '4W'");
    error.statusCode = 400;
    error.code = "INVALID_INPUT";
    throw error;
  }

  if (!GATE_IDS.has(gateId)) {
    const error = new TypeError("gateId must be Entry-1 or Entry-2");
    error.statusCode = 400;
    error.code = "INVALID_INPUT";
    throw error;
  }

  if (!operatorId) {
    const error = new TypeError("operatorId is required");
    error.statusCode = 400;
    error.code = "INVALID_INPUT";
    throw error;
  }

  const normalizedPlate = plateNumber.trim().toUpperCase();

  // Atomic compare-and-set: only one request can change a given free spot.
  // Sorting by spotNumber makes the selection deterministic and FCFS requests
  // are handled in the order in which this service receives them.
  const spot = await Spot.findOneAndUpdate(
    { zone: vehicleType, status: "free" },
    { $set: { status: "reserved" } },
    { new: true, sort: { spotNumber: 1 }, runValidators: true },
  );

  if (!spot) {
    const error = new Error("No free parking spot is available for this vehicle type");
    error.code = "LOT_FULL";
    error.statusCode = 409;
    throw error;
  }

  try {
    await Vehicle.findOneAndUpdate(
      { plateNumber: normalizedPlate },
      {
        $set: { vehicleType },
        $setOnInsert: { plateNumber: normalizedPlate },
      },
      { upsert: true, new: true, runValidators: true, setDefaultsOnInsert: true },
    );

    const entryTimestamp = new Date();
    const ticketId = `TKT-${entryTimestamp.toISOString().replace(/[-:.TZ]/g, "")}-${randomUUID().slice(0, 8).toUpperCase()}`;
    const transaction = await Transaction.create({
      ticketId,
      plateNumber: normalizedPlate,
      vehicleType,
      spotId: spot._id,
      entryGateId: gateId,
      entryOperatorId: operatorId,
      entryTimestamp,
      status: "active",
    });

    // Link the claimed spot to its active transaction when the model supports it.
    if (transaction?._id && spot._id) {
      await Spot.findOneAndUpdate(
        { _id: spot._id },
        { $set: { currentTransactionId: transaction._id } },
        { new: true },
      );
    }

    return {
      ticketId,
      transactionId: transaction?._id,
      spotId: String(spot._id),
      spotNumber: spot.spotNumber,
      zone: spot.zone || vehicleType,
      entryTimestamp,
      qrPayload: JSON.stringify({
        ticketId,
        plateNumber: normalizedPlate,
        vehicleType,
        spotId: String(spot._id),
      }),
    };
  } catch (error) {
    // Do not leave a spot reserved if persistence of the entry fails.
    await Spot.findOneAndUpdate(
      { _id: spot._id, status: "reserved" },
      { $set: { status: "free", currentTransactionId: null } },
      { new: true },
    );
    throw error;
  }
}

module.exports = { allocateSpot };
